module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);

    wire signed [31:0] signed_a;
    wire signed [31:0] signed_b;
    reg [32:0] res;
    reg [4:0] shift_amount;
    assign signed_a = $signed(a);
    assign signed_b = $signed(b);
    assign r = res[31:0];
    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;
    assign zero = (res[31:0] == 0);
    assign carry = res[32];
    assign negative = res[31];
    assign overflow = res[32];
    always @(*) begin
        case(aluc)
            ADD: res <= signed_a + signed_b;
            ADDU: res <= a + b;
            SUB: res <= signed_a - signed_b;
            SUBU: res <= a - b;
            AND: res <= a & b;
            OR: res <= a | b;
            XOR: res <= a ^ b;
            NOR: res <= ~(a | b);
            SLT: res <= (signed_a < signed_b) ? 1 : 0;
            SLTU: res <= (a < b) ? 1 : 0;
            SLL: res <= b << a[4:0];
            SRL: res <= b >> a[4:0];
            SRA: res <= signed_b >>> a[4:0];
            SLLV: res <= b << a[4:0];
            SRLV: res <= b >> a[4:0];
            SRAV: res <= signed_b >>> a[4:0];
            LUI: res <= {a[15:0], 16'h0};
            default: res <= 33'hzzzzzzzzz;
        endcase
    end

endmodule
